import*as b64u from"../util/base64url.js";import{decoder}from"../lib/buffer_utils.js";import{JWTInvalid}from"../util/errors.js";import{validateClaimsSet,JWTClaimsBuilder}from"../lib/jwt_claims_set.js";export class UnsecuredJWT{#t;constructor(t={}){this.#t=new JWTClaimsBuilder(t)}encode(){return`${b64u.encode(JSON.stringify({alg:"none"}))}.${b64u.encode(this.#t.data())}.`}setIssuer(t){return this.#t.iss=t,this}setSubject(t){return this.#t.sub=t,this}setAudience(t){return this.#t.aud=t,this}setJti(t){return this.#t.jti=t,this}setNotBefore(t){return this.#t.nbf=t,this}setExpirationTime(t){return this.#t.exp=t,this}setIssuedAt(t){return this.#t.iat=t,this}static decode(t,e){if("string"!=typeof t)throw new JWTInvalid("Unsecured JWT must be a string");const{0:s,1:r,2:i,length:n}=t.split(".");if(3!==n||""!==i)throw new JWTInvalid("Invalid Unsecured JWT");let d;try{if(d=JSON.parse(decoder.decode(b64u.decode(s))),"none"!==d.alg)throw new Error}catch{throw new JWTInvalid("Invalid Unsecured JWT")}return{payload:validateClaimsSet(d,b64u.decode(r),e),header:d}}}